from scipy.optimize import least_squares
base=np.column_stack([np.ones_like(t),x,v,v*np.abs(v),x**3,v**3,x**2*v,x*v**2])
def fit(model, p0s):
    best=None
    for p0 in p0s:
        try:
            r=least_squares(lambda p: model(p)-dv_dt, p0, max_nfev=3000)
            n=np.mean(r.fun**2)/np.var(dv_dt)
            if best is None or n<best[0]: best=(n,r.x)
        except Exception as e: pass
    return best
# model a: linear-in-params base + exp(-l t) cos(w t + p)
def ma(p):
    c=p[:8]; l,w,ph=p[8],p[9],p[10]
    return base@c[:8]*0 + base@c[:8] + p[11]*np.exp(-l*t)*np.cos(w*t+ph)
