    return (params[0] + params[1]*x + params[2]*x**3 + params[3]*v + params[4]*v*np.abs(v)
            + params[5]*v**3 + params[6]*np.sin(v) + params[7]*np.cos(v)
            + params[8]*np.cos(w*t) + params[9]*0.0 + 0.0*x)
